tool.command:
## HiCExplorer 3.7.6 ships hicMergeTADbins as a module without a
## console script; HiCExplorer 4 provides the executable.
merge_tad_bins() {
    if command -v @BINARY@ > /dev/null 2>&1; then
        @BINARY@ "\$@";
    else
        python -c 'import sys; from hicexplorer.hicMergeTADbins import main; main(sys.argv[1:])' "\$@";
    fi;
} &&
ln -s '$matrix_h5_cooler' 'matrix.$matrix_h5_cooler.ext' &&
merge_tad_bins
    --matrix 'matrix.$matrix_h5_cooler.ext'
    --domains '$domains'
    --outFile 'merged.$matrix_h5_cooler.ext' &&
mv 'merged.$matrix_h5_cooler.ext' merged_matrix
